# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人不断讲述工作细节，却很少谈自己的感受。咨询师既担心会谈停留在表面，又不想强行推进。请设计探索阶段的回应。
## 📌 参考思路
参考要点：先共情并总结工作事件；说明探索目的；以试探语气邀请关注感受和意义；核对当事人是否愿意；从多个主题中共同选择焦点；尊重节奏并持续检查联盟，不直接解释或强迫暴露。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid);
update public.chapter_review_notes set content = '# 【第四章 探索内容的技术】
## 🎯 本章目标
掌握重述、开放式提问、封闭式提问、鼓励、澄清、总结与结构化等内容探索技术。
## 🧭 学习主线
倾听关键内容 → 用鼓励保持叙述 → 重述与澄清 → 必要时提问 → 阶段性总结 → 共同选择下一焦点。
---PAGE---
# 【重述】
## 🧠 考试定义
用更简洁的语言表达当事人刚才陈述的核心内容，以确认理解并促进继续探索。
## 💬 如何向来访者解释
我听到的是，你一方面想离开，另一方面又担心让家人失望。
## 🧩 应用情境
当事人说了长段经历后，咨询师抓住关键事件和意义重新表达。
## ⚠️ 易错点
机械重复原话，或在重述中加入未经核对的解释。
---PAGE---
# 【开放式提问】
## 🧠 考试定义
邀请当事人用较自由、丰富的方式叙述经验，通常不能只用是或否回答。
## 💬 如何向来访者解释
你愿意多说一些那段经历对你的影响吗？
## 🧩 应用情境
使用“那件事发生后你有哪些反应”扩展信息。
## ⚠️ 易错点
连续抛出多个为什么，使当事人感到审问。
---PAGE---
# 【封闭式提问】
## 🧠 考试定义
用于获得具体、限定信息，通常可用简短事实或是非作答。
## 💬 如何向来访者解释
这周这样的情况发生了几次？
## 🧩 应用情境
核对时间、频率、风险和设置等必要事实。
## ⚠️ 易错点
用大量封闭问题主导整场会谈，使叙述碎片化。
---PAGE---
# 【最小鼓励】
## 🧠 考试定义
用简短词语、声音、点头或停顿表达正在倾听，鼓励当事人继续。
## 💬 如何向来访者解释
我在听，你可以按自己的节奏继续。
## 🧩 应用情境
在当事人停顿但仍在思考时，用“嗯”“然后呢”保持空间。
## ⚠️ 易错点
频繁、机械回应，打断当事人的节奏。
---PAGE---
# 【澄清】
## 🧠 考试定义
针对含糊、矛盾或指代不清的内容请求进一步说明，以减少误解。
## 💬 如何向来访者解释
我想确认一下，你说的“受不了”具体是指哪一种感受或情况？
## 🧩 应用情境
当事人说“他们都这样”时询问“这里的他们具体指谁”。
## ⚠️ 易错点
把澄清变成质疑当事人的真实性。
---PAGE---
# 【总结】
## 🧠 考试定义
整合一段会谈中的主题、情感、矛盾和进展，帮助形成连贯理解。
## 💬 如何向来访者解释
今天我们谈到三个部分，我先整理一下，你听听是否准确。
## 🧩 应用情境
转换主题或会谈结束前回顾重点，并邀请当事人修正。
## ⚠️ 易错点
只罗列事件，不呈现主题；或总结后不给当事人回应机会。
---PAGE---
# 【结构化】
## 🧠 考试定义
通过说明时间、目标、步骤和角色，使会谈保持清晰边界与方向。
## 💬 如何向来访者解释
我们还有二十分钟，可以继续这个主题，也可以留出时间讨论下一步，你更希望怎样安排？
## 🧩 应用情境
会谈开始共同确定议程，偏离较远时温和提醒剩余时间。
## ⚠️ 易错点
把结构化变成僵化控制，不允许重要新内容出现。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人在十分钟内讲了家庭、工作和身体三个主题，内容跳跃。请组合至少四种内容探索技术，帮助其形成清晰焦点。
## 📌 参考思路
参考要点：用最小鼓励完成当前叙述；重述主要内容；澄清关键指代和事实；总结三个主题及共同线索；用开放式提问了解最困扰部分；通过结构化说明时间并共同选择焦点；避免连续审问或咨询师单方面定题。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, '# 【第四章 探索内容的技术】
## 🎯 本章目标
掌握重述、开放式提问、封闭式提问、鼓励、澄清、总结与结构化等内容探索技术。
## 🧭 学习主线
倾听关键内容 → 用鼓励保持叙述 → 重述与澄清 → 必要时提问 → 阶段性总结 → 共同选择下一焦点。
---PAGE---
# 【重述】
## 🧠 考试定义
用更简洁的语言表达当事人刚才陈述的核心内容，以确认理解并促进继续探索。
## 💬 如何向来访者解释
我听到的是，你一方面想离开，另一方面又担心让家人失望。
## 🧩 应用情境
当事人说了长段经历后，咨询师抓住关键事件和意义重新表达。
## ⚠️ 易错点
机械重复原话，或在重述中加入未经核对的解释。
---PAGE---
# 【开放式提问】
## 🧠 考试定义
邀请当事人用较自由、丰富的方式叙述经验，通常不能只用是或否回答。
## 💬 如何向来访者解释
你愿意多说一些那段经历对你的影响吗？
## 🧩 应用情境
使用“那件事发生后你有哪些反应”扩展信息。
## ⚠️ 易错点
连续抛出多个为什么，使当事人感到审问。
---PAGE---
# 【封闭式提问】
## 🧠 考试定义
用于获得具体、限定信息，通常可用简短事实或是非作答。
## 💬 如何向来访者解释
这周这样的情况发生了几次？
## 🧩 应用情境
核对时间、频率、风险和设置等必要事实。
## ⚠️ 易错点
用大量封闭问题主导整场会谈，使叙述碎片化。
---PAGE---
# 【最小鼓励】
## 🧠 考试定义
用简短词语、声音、点头或停顿表达正在倾听，鼓励当事人继续。
## 💬 如何向来访者解释
我在听，你可以按自己的节奏继续。
## 🧩 应用情境
在当事人停顿但仍在思考时，用“嗯”“然后呢”保持空间。
## ⚠️ 易错点
频繁、机械回应，打断当事人的节奏。
---PAGE---
# 【澄清】
## 🧠 考试定义
针对含糊、矛盾或指代不清的内容请求进一步说明，以减少误解。
## 💬 如何向来访者解释
我想确认一下，你说的“受不了”具体是指哪一种感受或情况？
## 🧩 应用情境
当事人说“他们都这样”时询问“这里的他们具体指谁”。
## ⚠️ 易错点
把澄清变成质疑当事人的真实性。
---PAGE---
# 【总结】
## 🧠 考试定义
整合一段会谈中的主题、情感、矛盾和进展，帮助形成连贯理解。
## 💬 如何向来访者解释
今天我们谈到三个部分，我先整理一下，你听听是否准确。
## 🧩 应用情境
转换主题或会谈结束前回顾重点，并邀请当事人修正。
## ⚠️ 易错点
只罗列事件，不呈现主题；或总结后不给当事人回应机会。
---PAGE---
# 【结构化】
## 🧠 考试定义
通过说明时间、目标、步骤和角色，使会谈保持清晰边界与方向。
## 💬 如何向来访者解释
我们还有二十分钟，可以继续这个主题，也可以留出时间讨论下一步，你更希望怎样安排？
## 🧩 应用情境
会谈开始共同确定议程，偏离较远时温和提醒剩余时间。
## ⚠️ 易错点
把结构化变成僵化控制，不允许重要新内容出现。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人在十分钟内讲了家庭、工作和身体三个主题，内容跳跃。请组合至少四种内容探索技术，帮助其形成清晰焦点。
## 📌 参考思路
参考要点：用最小鼓励完成当前叙述；重述主要内容；澄清关键指代和事实；总结三个主题及共同线索；用开放式提问了解最困扰部分；通过结构化说明时间并共同选择焦点；避免连续审问或咨询师单方面定题。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid);
update public.chapter_review_notes set content = '# 【第五章 探索情感的技术】
## 🎯 本章目标
识别显性与隐性情感，使用情感反映、情感澄清和适度深化，帮助当事人准确体验和表达情绪。
## 🧭 学习主线
观察语言与非语言线索 → 提出试探性情感词 → 核对准确性与强度 → 探索触发和意义 → 调节深度。
---PAGE---
# 【情感反映】
## 🧠 考试定义
用语言表达咨询师从当事人叙述与非语言线索中理解到的核心情绪。
## 💬 如何向来访者解释
听起来你既松了一口气，又有一些失落，对吗？
## 🧩 应用情境
当事人微笑着讲失去时，试探回应“笑容背后似乎也有难过”。
## ⚠️ 易错点
只重复事件内容，或把咨询师自己的情绪归给当事人。
---PAGE---
# 【显性情感】
## 🧠 考试定义
当事人直接说出或清楚表现出来、较容易被识别的情绪。
## 💬 如何向来访者解释
你已经很清楚地感觉到生气，我们可以再看看这份生气指向什么。
## 🧩 应用情境
当事人说“我很生气”时先准确回应，再探索其意义。
## ⚠️ 易错点
因为情绪已说出口就不再核对强度和对象。
---PAGE---
# 【隐性情感】
## 🧠 考试定义
未被直接说出、但可从语气、身体、矛盾或情境中推测的情绪。
## 💬 如何向来访者解释
我不确定是否准确，我听到这里时猜想也许有一点害怕，你怎么看？
## 🧩 应用情境
用试探语气反映可能存在的羞耻或害怕，并允许否认。
## ⚠️ 易错点
把推测当事实，以权威口吻揭示“真正情绪”。
---PAGE---
# 【混合情感】
## 🧠 考试定义
同一事件中同时存在方向不同或相互冲突的多种情绪。
## 💬 如何向来访者解释
对同一件事同时轻松和难过并不矛盾，我们可以分别理解它们。
## 🧩 应用情境
帮助当事人同时容纳对离开关系的轻松与悲伤。
## ⚠️ 易错点
要求当事人选出唯一“真实”情绪。
---PAGE---
# 【情感强度】
## 🧠 考试定义
情绪体验的程度、持续性和对功能的影响，需要用贴近当事人的词语和尺度核对。
## 💬 如何向来访者解释
如果0代表没有、10代表最强，现在大约是多少？
## 🧩 应用情境
询问0到10的强度，并区分烦躁、愤怒和暴怒。
## ⚠️ 易错点
使用过强情感词放大体验，或用过弱词淡化痛苦。
---PAGE---
# 【情感深化】
## 🧠 考试定义
在安全和联盟允许时，从表层情绪逐步接近更核心的需要、脆弱和意义。
## 💬 如何向来访者解释
我们可以稍微靠近这份愤怒下面的感受，但节奏由你决定。
## 🧩 应用情境
从愤怒进一步探索被忽视、受伤或害怕失去。
## ⚠️ 易错点
越深越好，不顾当事人的准备和情绪承受窗口。
---PAGE---
# 【情感调节窗口】
## 🧠 考试定义
当事人能够保持连接、思考和体验而不过度淹没或麻木的可工作唤起范围。
## 💬 如何向来访者解释
如果现在太强烈，我们先让身体稳定下来，再决定是否继续。
## 🧩 应用情境
出现明显失控或解离线索时先稳定、定向和放慢。
## ⚠️ 易错点
把强烈宣泄本身当作治疗目标，忽略安全与整合。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人笑着说“没什么，只是父亲去世后我终于自由了”，随后沉默并握紧双手。请说明咨询师如何使用情感探索技术。
## 📌 参考思路
参考要点：观察语言与非语言不一致；先用试探性的情感反映；允许混合情感并核对强度；探索自由、悲伤、内疚或害怕等可能意义；留意调节窗口，必要时稳定和放慢；不武断揭示、不强迫哭泣或宣泄。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid;
