定期询问当事人对关系、目标、任务、节奏和帮助程度的看法。
## 💬 如何向来访者解释
请告诉我今天哪部分有帮助、哪部分需要我做得不同。
## 🧩 应用情境
每次会谈末询问最有帮助和需要改变的部分。
## ⚠️ 易错点
只在结束时进行满意度调查。
---PAGE---
# 【整合一致性】
## 🧠 考试定义
不同技术应围绕共同概念化、目标和关系逻辑协调使用。
## 💬 如何向来访者解释
我们使用的不同方法会围绕同一个目标，而不是彼此冲突。
## 🧩 应用情境
所有阶段技术都指向减少回避并增加真实表达。
## ⚠️ 易错点
从不同流派随意拼接互相矛盾的做法。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人在会谈中理解了回避模式并同意行动任务，但执行后焦虑显著升高并开始质疑咨询关系。请用三阶段模型重新安排工作。
## 📌 参考思路
参考要点：暂停机械推进行动；评估风险和焦虑程度；回到探索行动后的体验和关系破裂；修复联盟；更新概念化，理解任务难度、信念和环境障碍；重新判断阶段；必要时缩小任务或先训练调节技能；持续使用过程反馈。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid);
update public.chapter_review_notes set content = '# 【第十六章 结束咨询】
## 🎯 本章目标
把结束视为助人过程的重要阶段，通过计划、回顾、情感处理、复发预防和资源安排促进自主与持续改变。
## 🧭 学习主线
提前讨论结束 → 回顾目标与变化 → 处理分离情感 → 总结有效方法 → 制定复发预防与资源计划 → 完成告别和随访安排。
---PAGE---
# 【计划性结束】
## 🧠 考试定义
根据目标进展、时间和服务设置提前协商结束，而非突然终止。
## 💬 如何向来访者解释
我们会提前一起计划结束，让你有时间准备和表达感受。
## 🧩 应用情境
在剩余数次会谈时开始讨论结束日期和任务。
## ⚠️ 易错点
等到最后一次才告知，或无限延长以避免分离。
---PAGE---
# 【结束评估】
## 🧠 考试定义
综合目标完成、功能变化、剩余风险、资源和自主能力判断结束是否合适。
## 💬 如何向来访者解释
我们会一起看哪些目标已实现、哪些仍需支持，再决定结束安排。
## 🧩 应用情境
比较基线、目标进展和当事人自我评价。
## ⚠️ 易错点
仅因症状短期下降就忽略风险和维持计划。
---PAGE---
# 【回顾与巩固】
## 🧠 考试定义
总结关键领悟、有效技能、关系经验和当事人自身贡献，使改变可被带走。
## 💬 如何向来访者解释
这些改变主要来自你的投入，我们一起总结你已经学会了什么。
## 🧩 应用情境
让当事人列出最有用的方法和如何继续使用。
## ⚠️ 易错点
把成果全部归功于咨询师或技术。
---PAGE---
# 【结束情感】
## 🧠 考试定义
结束可能引发不舍、焦虑、愤怒、轻松或被抛弃感，需要被允许和理解。
## 💬 如何向来访者解释
结束可能同时让人轻松和不舍，这些感受都可以在这里谈。
## 🧩 应用情境
主动邀请讨论对结束的复杂感受。
## ⚠️ 易错点
只强调庆祝，回避负面或矛盾情绪。
---PAGE---
# 【复发预防】
## 🧠 考试定义
识别高风险情境、早期信号、有效应对和求助条件，减少旧模式再次主导。
## 💬 如何向来访者解释
以后有波动并不等于前功尽弃，重要的是尽早识别并使用计划。
## 🧩 应用情境
制作触发—信号—应对—求助的书面计划。
## ⚠️ 易错点
承诺问题永不复发，或把波动视为失败。
---PAGE---
# 【资源与转介】
## 🧠 考试定义
在结束前确认自然支持、专业资源、紧急渠道和必要的后续服务。
## 💬 如何向来访者解释
结束后你仍可以使用这些支持；如果出现哪些情况，需要及时联系相应资源。
## 🧩 应用情境
仍有风险或特殊需求时讨论转介并完成衔接。
## ⚠️ 易错点
结束就完全切断，不提供必要资源；或制造持续依赖。
---PAGE---
# 【非计划终止】
## 🧠 考试定义
当事人突然停止、失联或因外部原因结束时，在伦理和设置范围内尝试联系、评估风险并记录。
## 💬 如何向来访者解释
如果你想提前结束，可以告诉我；我们尽量安排一次总结和安全计划。
## 🧩 应用情境
高风险当事人失联时按约定和机构流程进行安全处置。
## ⚠️ 易错点
反复追踪侵犯边界，或因感到被拒绝而完全不处理。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
长期来访者在目标明显改善后说“我一想到结束就觉得你也会抛弃我”，并要求无限期继续。请设计结束阶段工作。
## 📌 参考思路
参考要点：共情并允许分离与被抛弃感；把结束作为关系模式的工作机会；共同评估目标、风险和自主能力；提前计划结束时间；回顾当事人贡献和有效技能；制定复发预防、资源和求助条件；保持边界，不因咨询师或当事人的不舍无限延长。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, '# 【第十六章 结束咨询】
