-- Protected content for 心理测量与评估.
insert into public.course_brief (course_id, exam_date, exam_structure, assignments, study_tips) values ('bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid, '2026-07-19'::date, '课堂考勤 5%；课堂参与 10%；平时作业 45%；期末考核 40%。期末复习以选择题为主，重点考查概念辨析、工具选择、结果解释和临床情境应用。', '作业1：完成一次结构化初始访谈，重点考查前期准备、知情同意、初评框架、时间节奏、风险筛查和信息整合。作业2：量表检索，围绕评估问题查找并比较工具的用途、适用人群、信效度、常模、施测计分和解释限制。', '先掌握“测量—测评—测验”“信度—效度”“筛查—评估—诊断”等核心区别，再用情境题练习选择工具和下一步处理。初始评估、危机评估、人格评估为最高优先级；任何风险题先考虑安全、保密例外、升级处置和记录。')
on conflict (course_id) do update set exam_date = excluded.exam_date, exam_structure = excluded.exam_structure, assignments = excluded.assignments, study_tips = excluded.study_tips;

update public.chapter_review_notes set content = '# 【第一章 心理测量与评估基础】
## 🎯 本章目标
区分测量、测评与测验，理解心理评估的目的、信息来源、标准化要求和伦理边界。
## 🧭 学习主线
明确转介问题 → 选择信息来源与工具 → 规范施测 → 结合常模和情境解释 → 整合反馈与跟进。
---PAGE---
# 【心理测量】
## 🧠 考试定义
依据心理学理论和规则，对心理特质或行为进行定量描述的活动。
## 💬 如何向来访者解释
量表分数只是把某一方面转成可比较的数据，并不能代表你的全部。
## 🧩 应用情境
需要量化焦虑程度并监测变化时选择合适的测量工具。
## ⚠️ 易错点
把一次分数当作完整、无误差的人格结论。
---PAGE---
# 【心理测评】
## 🧠 考试定义
围绕评估问题整合访谈、观察、记录、量表和标准化测验等信息，形成判断和建议的过程。
## 💬 如何向来访者解释
评估会结合多种信息来理解问题，量表只是其中一部分。
## 🧩 应用情境
咨询初评中同时使用访谈、行为观察和量表，而不是只发问卷。
## ⚠️ 易错点
心理测评等同于做一份量表并报告分数。
---PAGE---
# 【心理测验】
## 🧠 考试定义
按照标准程序测量行为样本，并借助计分和解释规则推断相关心理特征的工具或方法。
## 💬 如何向来访者解释
测验观察的是有限行为样本，因此结果需要结合其他信息理解。
## 🧩 应用情境
使用标准指导语和规定计分方法完成能力测验。
## ⚠️ 易错点
测验能直接测到完整的内在特质且没有误差。
---PAGE---
# 【标准化】
## 🧠 考试定义
在施测材料、指导语、环境、计分和解释等方面保持统一，以提高结果可比性。
## 💬 如何向来访者解释
统一流程能让你的结果更可比较；若流程有调整，我们会在解释中说明。
## 🧩 应用情境
不同来访者使用相同指导语和计时规则。
## ⚠️ 易错点
为让来访者表现更好而随意改变题目或提示。
---PAGE---
# 【常模参照】
## 🧠 考试定义
把个体分数与具有明确特征的参照群体分布进行比较。
## 💬 如何向来访者解释
这个位置表示你与合适参照群体相比的大致水平，不是能力的绝对上限。
## 🧩 应用情境
解释儿童得分时使用年龄和文化背景合适的常模。
## ⚠️ 易错点
百分位代表答对百分比，或任何常模都适合所有人。
---PAGE---
# 【效标参照】
## 🧠 考试定义
根据预先规定的标准或掌握水平判断个体是否达到要求，而非主要比较群体位置。
## 💬 如何向来访者解释
这里关注的是是否达到某个标准，而不是你排在别人前面还是后面。
## 🧩 应用情境
判断某项技能是否达到临床或教学设定标准。
## ⚠️ 易错点
效标参照必须依赖常模排名才能解释。
---PAGE---
# 【评估问题】
## 🧠 考试定义
评估需要回答的具体临床、教育或决策问题，是选择工具和解释结果的起点。
## 💬 如何向来访者解释
我们先明确希望评估回答什么问题，再决定需要哪些信息。
## 🧩 应用情境
把“了解孩子”改为“解释阅读困难并形成干预建议”。
## ⚠️ 易错点
先选熟悉的量表，再寻找可以回答的问题。
---PAGE---
# 【评估伦理】
## 🧠 考试定义
在知情同意、胜任力、隐私、工具安全、公平解释和结果使用方面保护受评者权益。
## 💬 如何向来访者解释
你有权知道为什么评估、结果如何使用、谁能看到以及它有哪些局限。
## 🧩 应用情境
说明目的、用途、局限和保密例外，使用有授权且胜任的工具。
## ⚠️ 易错点
未经说明把结果提供给第三方，或超出胜任力解释。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
一位咨询师只依据网络人格问卷的高分便告诉来访者“你一定有人格障碍”。请指出评估流程和伦理问题，并提出规范做法。
## 📌 参考思路
参考要点：区分测验与完整测评；网络问卷的标准化、常模、信效度和适用范围需核查；量表不能单独诊断；应从转介问题出发，结合访谈、观察、历史和多源信息；说明局限并获得知情同意；超出胜任力时转介。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, '# 【第一章 心理测量与评估基础】
## 🎯 本章目标
区分测量、测评与测验，理解心理评估的目的、信息来源、标准化要求和伦理边界。
## 🧭 学习主线
明确转介问题 → 选择信息来源与工具 → 规范施测 → 结合常模和情境解释 → 整合反馈与跟进。
---PAGE---
# 【心理测量】
## 🧠 考试定义
依据心理学理论和规则，对心理特质或行为进行定量描述的活动。
## 💬 如何向来访者解释
量表分数只是把某一方面转成可比较的数据，并不能代表你的全部。
## 🧩 应用情境
需要量化焦虑程度并监测变化时选择合适的测量工具。
## ⚠️ 易错点
把一次分数当作完整、无误差的人格结论。
---PAGE---
# 【心理测评】
## 🧠 考试定义
围绕评估问题整合访谈、观察、记录、量表和标准化测验等信息，形成判断和建议的过程。
## 💬 如何向来访者解释
评估会结合多种信息来理解问题，量表只是其中一部分。
## 🧩 应用情境
咨询初评中同时使用访谈、行为观察和量表，而不是只发问卷。
## ⚠️ 易错点
心理测评等同于做一份量表并报告分数。
---PAGE---
# 【心理测验】
## 🧠 考试定义
按照标准程序测量行为样本，并借助计分和解释规则推断相关心理特征的工具或方法。
## 💬 如何向来访者解释
测验观察的是有限行为样本，因此结果需要结合其他信息理解。
## 🧩 应用情境
使用标准指导语和规定计分方法完成能力测验。
## ⚠️ 易错点
测验能直接测到完整的内在特质且没有误差。
---PAGE---
# 【标准化】
## 🧠 考试定义
在施测材料、指导语、环境、计分和解释等方面保持统一，以提高结果可比性。
## 💬 如何向来访者解释
统一流程能让你的结果更可比较；若流程有调整，我们会在解释中说明。
## 🧩 应用情境
不同来访者使用相同指导语和计时规则。
## ⚠️ 易错点
为让来访者表现更好而随意改变题目或提示。
---PAGE---
# 【常模参照】
## 🧠 考试定义
把个体分数与具有明确特征的参照群体分布进行比较。
## 💬 如何向来访者解释
这个位置表示你与合适参照群体相比的大致水平，不是能力的绝对上限。
## 🧩 应用情境
解释儿童得分时使用年龄和文化背景合适的常模。
## ⚠️ 易错点
百分位代表答对百分比，或任何常模都适合所有人。
---PAGE---
# 【效标参照】
## 🧠 考试定义
根据预先规定的标准或掌握水平判断个体是否达到要求，而非主要比较群体位置。
## 💬 如何向来访者解释
这里关注的是是否达到某个标准，而不是你排在别人前面还是后面。
## 🧩 应用情境
判断某项技能是否达到临床或教学设定标准。
## ⚠️ 易错点
效标参照必须依赖常模排名才能解释。
---PAGE---
# 【评估问题】
## 🧠 考试定义
评估需要回答的具体临床、教育或决策问题，是选择工具和解释结果的起点。
## 💬 如何向来访者解释
我们先明确希望评估回答什么问题，再决定需要哪些信息。
## 🧩 应用情境
把“了解孩子”改为“解释阅读困难并形成干预建议”。
## ⚠️ 易错点
先选熟悉的量表，再寻找可以回答的问题。
---PAGE---
# 【评估伦理】
## 🧠 考试定义
在知情同意、胜任力、隐私、工具安全、公平解释和结果使用方面保护受评者权益。
## 💬 如何向来访者解释
你有权知道为什么评估、结果如何使用、谁能看到以及它有哪些局限。
## 🧩 应用情境
说明目的、用途、局限和保密例外，使用有授权且胜任的工具。
## ⚠️ 易错点
未经说明把结果提供给第三方，或超出胜任力解释。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
一位咨询师只依据网络人格问卷的高分便告诉来访者“你一定有人格障碍”。请指出评估流程和伦理问题，并提出规范做法。
## 📌 参考思路
参考要点：区分测验与完整测评；网络问卷的标准化、常模、信效度和适用范围需核查；量表不能单独诊断；应从转介问题出发，结合访谈、观察、历史和多源信息；说明局限并获得知情同意；超出胜任力时转介。' where not exists (select 1 from public.chapter_review_notes where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid);
update public.chapter_review_notes set content = '# 【第二章 测量理论、信度与效度】
## 🎯 本章目标
掌握经典测量理论、测量误差、信度和效度的定义、类别、关系及临床解释。
## 🧭 学习主线
明确分数用途 → 识别误差来源 → 查看信度证据 → 查看效度证据 → 判断适用范围 → 谨慎解释。
---PAGE---
# 【经典测量理论】
## 🧠 考试定义
认为观察分数由真分数与误差分数组成，即X=T+E。
## 💬 如何向来访者解释
你看到的是一次观察分数，其中既有相对稳定部分，也会受到误差影响。
## 🧩 应用情境
解释一次得分时同时考虑真实水平和测量误差。
## ⚠️ 易错点
观察分数就是真分数，重复测量不会变化。
---PAGE---
# 【测量误差】
## 🧠 考试定义
使观察分数偏离目标真分数的随机或系统影响，来源可包括受评者、施测、环境和计分。
## 💬 如何向来访者解释
当天状态和环境可能影响分数，因此我们会结合这些情况解释。
## 🧩 应用情境
睡眠不足、噪声和指导语变化都需记录并纳入解释。
## ⚠️ 易错点
误差只来自量表质量，与施测环境和受评者状态无关。
---PAGE---
# 【信度】
## 🧠 考试定义
测量结果的一致性、稳定性或精确程度，是分数可解释的必要条件。
## 💬 如何向来访者解释
信度说明结果够不够稳定，但还不能单独证明测量内容正确。
## 🧩 应用情境
同一工具在相似条件下结果大幅波动时不能据此做重要决策。
## ⚠️ 易错点
信度高就说明一定测到了目标构念。
---PAGE---
# 【重测信度】
## 🧠 考试定义
同一工具在两个时间点对同一群体施测所得分数的一致性。
## 💬 如何向来访者解释
它反映一段时间后的稳定程度，但也会受真实变化和间隔影响。
## 🧩 应用情境
评估相对稳定特质时查看适当时间间隔的重测证据。
## ⚠️ 易错点
间隔越短或越长都必然越好，且任何构念都应高度稳定。
---PAGE---
# 【内部一致性】
## 🧠 考试定义
测验内部条目在测量同一构念方面的一致程度。
## 💬 如何向来访者解释
它说明题目是否大体朝向同一内容，但不能替代效度证据。
## 🧩 应用情境
多条目单维量表可查看α或ω等内部一致性指标。
## ⚠️ 易错点
指标越接近1越好，极高值不可能来自条目重复。
---PAGE---
# 【评分者一致性】
## 🧠 考试定义
不同观察者或评分者对同一表现给出结果的一致程度。
## 💬 如何向来访者解释
当结果依赖人工判断时，需要确认不同评分者能否得到相近结论。
## 🧩 应用情境
行为编码或投射测验解释需要训练并报告评分者一致性。
## ⚠️ 易错点
只要评分者有经验，就无需统一标准或检查一致性。
---PAGE---
# 【效度】
## 🧠 考试定义
证据支持分数在特定用途和情境下解释是否合理的程度。
## 💬 如何向来访者解释
效度关注这个分数能否用于当前问题，而不是给量表贴一个永久标签。
## 🧩 应用情境
筛查工具用于诊断前需确认该用途是否有充分效度证据。
## ⚠️ 易错点
效度是工具永久不变的单一属性，对所有群体用途都相同。
---PAGE---
# 【效度证据】
## 🧠 考试定义
可从内容、内部结构、与其他变量关系、反应过程和使用后果等方面支持分数解释。
## 💬 如何向来访者解释
我们需要多类证据共同支持，而不是依赖一个相关系数。
## 🧩 应用情境
选择工具时同时查看内容覆盖、结构和效标关联。
## ⚠️ 易错点
只要与另一个量表相关较高，就证明所有用途都有效。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
某焦虑量表三次结果分别为18、35和22，另一份名为“抑郁筛查”的问卷实际主要测社交回避。请分别分析信度和效度风险。
## 📌 参考思路
参考要点：前者提示结果稳定性或施测条件存在问题，应检查时间间隔、状态、环境、计分及工具信度，不能贸然解释变化；后者属于分数解释与目标构念不匹配的效度风险，可能造成错误概念化；两者都需结合多源信息，不能单凭分数诊断。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '0d255644-6228-51df-bb46-2b7483ae1652'::uuid;
