update public.chapter_review_notes set content = '# 【第六章 初评量表、报告与结果反馈】
## 🎯 本章目标
把量表规范融入初评，完成施测、计分、解释、多源整合、报告撰写和以转介问题为中心的反馈。
## 🧭 学习主线
根据问题选量表 → 规范说明与施测 → 检查漏答和重点条目 → 正确计分 → 结合常模与临床信息解释 → 撰写报告 → 合作反馈与后续计划。
---PAGE---
# 【量表融合】
## 🧠 考试定义
把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。
## 💬 如何向来访者解释
量表帮助我们发现需要进一步了解的方向，不会单独决定诊断。
## 🧩 应用情境
抑郁量表高分后继续询问具体条目、功能和风险。
## ⚠️ 易错点
只要总分超过界值就直接诊断。
---PAGE---
# 【工具适配】
## 🧠 考试定义
确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。
## 💬 如何向来访者解释
我们会选择适合你的年龄和问题、且有研究依据的工具。
## 🧩 应用情境
为青少年选择有对应年龄常模和使用证据的工具。
## ⚠️ 易错点
只因量表简短或免费就使用。
---PAGE---
# 【施测前准备】
## 🧠 考试定义
熟悉指导语、计分、重点条目、材料设备和异常情况处理。
## 💬 如何向来访者解释
规范准备能减少流程差异，也避免遗漏重要信息。
## 🧩 应用情境
提前检查二维码、纸笔、年龄版本和计分规则。
## ⚠️ 易错点
边看说明书边施测，或不知道关键风险条目。
---PAGE---
# 【计分质控】
## 🧠 考试定义
计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。
## 💬 如何向来访者解释
有些题目即使不影响总分，也可能提示需要立即进一步询问。
## 🧩 应用情境
发现风险条目非零时先跟进安全问题，而不是只算总分。
## ⚠️ 易错点
总分正确就不必检查单个条目和作答质量。
---PAGE---
# 【分数解释】
## 🧠 考试定义
结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。
## 💬 如何向来访者解释
分数表示相对位置和风险线索，不是对你的固定定义。
## 🧩 应用情境
说明T分数位置、可信区间和常模适用范围。
## ⚠️ 易错点
把百分位当正确率，或把界值当绝对诊断线。
---PAGE---
# 【多源整合】
## 🧠 考试定义
比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。
## 💬 如何向来访者解释
不同来源不一致并不一定是谁错了，可能反映不同情境下的表现。
## 🧩 应用情境
家长报告、儿童自述和学校观察不一致时分析情境差异。
## ⚠️ 易错点
选择最符合咨询师预期的一项信息，其余忽略。
---PAGE---
# 【初评报告】
## 🧠 考试定义
用清晰结构记录转介问题、方法、行为观察、结果、整合解释、局限和建议。
## 💬 如何向来访者解释
报告会围绕最初问题整合信息，并清楚说明依据和局限。
## 🧩 应用情境
区分事实、来访报告、测验结果和专业推断。
## ⚠️ 易错点
堆砌分数而不回答转介问题，或把推断写成事实。
---PAGE---
# 【结果反馈】
## 🧠 考试定义
以可理解、合作和优势取向方式解释过程、结果、局限和建议，并收集来访反应。
## 💬 如何向来访者解释
我会用易理解的方式说明结果，也希望听到哪些部分符合或不符合你的体验。
## 🧩 应用情境
先回到转介问题，使用视觉材料，指出优势并讨论下一步。
## ⚠️ 易错点
照读报告、使用大量术语或只讲缺陷。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
初评中来访者抑郁量表总分中等，但自杀条目为3分；访谈时否认严重问题。请说明计分、询问、整合、报告和反馈步骤。
## 📌 参考思路
参考要点：先检查作答完整性和计分；风险条目优先于总分，立即直接跟进想法、计划、意图、手段和保护因素；比较量表、访谈、行为观察及可能的最小化反应；必要时启动危机流程；报告区分数据与推断并说明局限；反馈使用清晰语言、回归安全和后续计划。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, '# 【第六章 初评量表、报告与结果反馈】
