update public.chapter_review_notes set content = '# 【第十一章 发育行为与特殊人群评估】
## 🎯 本章目标
掌握儿童及特殊人群评估中的发展视角、多信息源、多情境观察、年龄常模、公平调整与家长反馈。
## 🧭 学习主线
明确发展与转介问题 → 收集多信息源历史 → 选择年龄文化适配工具 → 多情境观察与施测 → 比较一致和差异 → 形成发展性解释、反馈和支持建议。
---PAGE---
# 【发展性评估】
## 🧠 考试定义
把能力和行为放在年龄、发展阶段、学习机会和变化轨迹中理解。
## 💬 如何向来访者解释
孩子的表现需要放在当前发展阶段和成长轨迹中理解。
## 🧩 应用情境
同一行为在幼儿和青少年阶段的意义不同。
## ⚠️ 易错点
直接用成人标准判断儿童表现。
---PAGE---
# 【多信息提供者】
## 🧠 考试定义
综合儿童本人、家长、教师和其他照顾者在不同情境中的观察。
## 💬 如何向来访者解释
不同人看到的是不同情境，不一致本身能帮助定位问题。
## 🧩 应用情境
比较家庭与学校报告并探索情境差异。
## ⚠️ 易错点
报告不一致说明某一方不诚实。
---PAGE---
# 【发展史】
## 🧠 考试定义
收集孕产、里程碑、语言、运动、学习、医疗和社会情绪发展过程。
## 💬 如何向来访者解释
了解成长过程能帮助判断困难是一直存在还是最近出现。
## 🧩 应用情境
关注何时出现偏离、是否退步及环境变化。
## ⚠️ 易错点
只看当前量表，不需要早期发展信息。
---PAGE---
# 【适龄常模】
## 🧠 考试定义
使用与年龄、语言、文化和教育背景相匹配的参照资料解释表现。
## 💬 如何向来访者解释
儿童变化很快，必须使用适合当前年龄的参照。
## 🧩 应用情境
学龄前儿童使用对应年龄段规范版本。
## ⚠️ 易错点
同一工具和常模可跨年龄直接比较。
---PAGE---
# 【发育行为观察】
## 🧠 考试定义
在结构化任务和自然互动中观察注意、沟通、游戏、运动、情绪调节和社会互动。
## 💬 如何向来访者解释
评估室只是一个场景，我们还需要了解平时表现是否相同。
## 🧩 应用情境
结合测验室、家庭和学校行为判断代表性。
## ⚠️ 易错点
一次陌生环境表现可以代表所有日常行为。
---PAGE---
# 【自闭症与多动评估】
## 🧠 考试定义
对社交沟通、限制重复行为、注意冲动和跨情境功能进行多方法、发展性评估。
## 💬 如何向来访者解释
问卷只能提示进一步评估方向，诊断需要多来源和跨情境证据。
## 🧩 应用情境
量表筛查阳性后继续访谈、观察和鉴别。
## ⚠️ 易错点
一份家长问卷即可确诊自闭症或多动症。
---PAGE---
# 【学习与智力评估】
## 🧠 考试定义
综合认知、学业、语言、注意和教育机会，理解学习困难及支持需求。
## 💬 如何向来访者解释
学习困难可能来自多种原因，需要比较能力、教学和情境。
## 🧩 应用情境
比较学业技能、认知过程和教学经历。
## ⚠️ 易错点
低学业成绩必然等于智力低下或学习障碍。
---PAGE---
# 【合理调整】
## 🧠 考试定义
为感官、语言、运动或其他需要提供必要便利，同时记录对标准化和解释的影响。
## 💬 如何向来访者解释
适当便利能提高公平性，但我们会说明它对结果可比性的影响。
## 🧩 应用情境
为运动受限者调整作答方式并说明限制。
## ⚠️ 易错点
任何调整都不会影响结果，或为了标准化拒绝所有便利。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
教师报告儿童在课堂极度分心，家长称在家专注良好，筛查问卷结果也不一致。请设计进一步评估。
## 📌 参考思路
参考要点：不把不一致简单归因为谁不可信；收集发展、学习、睡眠、情绪和家庭学校情境；获取多信息提供者资料；进行课堂或结构化观察；选择适龄、适文化工具；评估注意冲动的跨情境和功能损害；鉴别教学、焦虑、学习困难等因素；反馈时说明情境差异和支持建议。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, '# 【第十一章 发育行为与特殊人群评估】
## 🎯 本章目标
掌握儿童及特殊人群评估中的发展视角、多信息源、多情境观察、年龄常模、公平调整与家长反馈。
## 🧭 学习主线
明确发展与转介问题 → 收集多信息源历史 → 选择年龄文化适配工具 → 多情境观察与施测 → 比较一致和差异 → 形成发展性解释、反馈和支持建议。
---PAGE---
# 【发展性评估】
## 🧠 考试定义
把能力和行为放在年龄、发展阶段、学习机会和变化轨迹中理解。
## 💬 如何向来访者解释
孩子的表现需要放在当前发展阶段和成长轨迹中理解。
## 🧩 应用情境
同一行为在幼儿和青少年阶段的意义不同。
## ⚠️ 易错点
直接用成人标准判断儿童表现。
---PAGE---
# 【多信息提供者】
## 🧠 考试定义
综合儿童本人、家长、教师和其他照顾者在不同情境中的观察。
## 💬 如何向来访者解释
不同人看到的是不同情境，不一致本身能帮助定位问题。
## 🧩 应用情境
比较家庭与学校报告并探索情境差异。
## ⚠️ 易错点
报告不一致说明某一方不诚实。
---PAGE---
# 【发展史】
## 🧠 考试定义
收集孕产、里程碑、语言、运动、学习、医疗和社会情绪发展过程。
## 💬 如何向来访者解释
了解成长过程能帮助判断困难是一直存在还是最近出现。
## 🧩 应用情境
关注何时出现偏离、是否退步及环境变化。
## ⚠️ 易错点
只看当前量表，不需要早期发展信息。
---PAGE---
# 【适龄常模】
## 🧠 考试定义
使用与年龄、语言、文化和教育背景相匹配的参照资料解释表现。
## 💬 如何向来访者解释
儿童变化很快，必须使用适合当前年龄的参照。
## 🧩 应用情境
学龄前儿童使用对应年龄段规范版本。
## ⚠️ 易错点
同一工具和常模可跨年龄直接比较。
---PAGE---
# 【发育行为观察】
## 🧠 考试定义
在结构化任务和自然互动中观察注意、沟通、游戏、运动、情绪调节和社会互动。
## 💬 如何向来访者解释
评估室只是一个场景，我们还需要了解平时表现是否相同。
## 🧩 应用情境
结合测验室、家庭和学校行为判断代表性。
## ⚠️ 易错点
一次陌生环境表现可以代表所有日常行为。
---PAGE---
# 【自闭症与多动评估】
## 🧠 考试定义
对社交沟通、限制重复行为、注意冲动和跨情境功能进行多方法、发展性评估。
## 💬 如何向来访者解释
问卷只能提示进一步评估方向，诊断需要多来源和跨情境证据。
## 🧩 应用情境
量表筛查阳性后继续访谈、观察和鉴别。
## ⚠️ 易错点
一份家长问卷即可确诊自闭症或多动症。
---PAGE---
# 【学习与智力评估】
## 🧠 考试定义
综合认知、学业、语言、注意和教育机会，理解学习困难及支持需求。
## 💬 如何向来访者解释
学习困难可能来自多种原因，需要比较能力、教学和情境。
## 🧩 应用情境
比较学业技能、认知过程和教学经历。
## ⚠️ 易错点
低学业成绩必然等于智力低下或学习障碍。
---PAGE---
# 【合理调整】
## 🧠 考试定义
为感官、语言、运动或其他需要提供必要便利，同时记录对标准化和解释的影响。
## 💬 如何向来访者解释
适当便利能提高公平性，但我们会说明它对结果可比性的影响。
## 🧩 应用情境
为运动受限者调整作答方式并说明限制。
## ⚠️ 易错点
任何调整都不会影响结果，或为了标准化拒绝所有便利。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
教师报告儿童在课堂极度分心，家长称在家专注良好，筛查问卷结果也不一致。请设计进一步评估。
## 📌 参考思路
参考要点：不把不一致简单归因为谁不可信；收集发展、学习、睡眠、情绪和家庭学校情境；获取多信息提供者资料；进行课堂或结构化观察；选择适龄、适文化工具；评估注意冲动的跨情境和功能损害；鉴别教学、焦虑、学习困难等因素；反馈时说明情境差异和支持建议。' where not exists (select 1 from public.chapter_review_notes where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid);
update public.chapter_review_notes set content = '# 【第十二章 治疗性、数智化评估与课程整合】
## 🎯 本章目标
理解治疗性评估、合作反馈、持续监测及AI和多模态数据带来的机会、偏差、隐私和责任问题。
## 🧭 学习主线
共同提出评估问题 → 选择传统与数字信息 → 保护同意和隐私 → 检查算法与数据质量 → 合作解释 → 转化为行动 → 持续监测和修正。
---PAGE---
# 【治疗性评估】
## 🧠 考试定义
把评估本身作为合作性干预，通过共同问题、体验和反馈促进理解与改变。
## 💬 如何向来访者解释
评估不只是得到分数，也可以帮助你形成新的理解和下一步。
## 🧩 应用情境
让来访提出希望评估回答的问题，并共同讨论结果意义。
## ⚠️ 易错点
评估者单向宣判结果，来访只负责接受。
---PAGE---
# 【合作反馈】
## 🧠 考试定义
评估者与受评者共同检验结果、差异和意义，允许修正并连接现实目标。
## 💬 如何向来访者解释
你的反应是解释的一部分，结果需要和你的经验放在一起。
## 🧩 应用情境
询问结果哪些符合、哪些不符合以及有什么新问题。
## ⚠️ 易错点
受评者不同意就说明缺乏洞察。
---PAGE---
# 【结果监测】
## 🧠 考试定义
在服务过程中重复使用适当指标追踪症状、功能、联盟和目标变化。
## 💬 如何向来访者解释
趋势比单次波动更重要，也要结合这段时间发生了什么。
## 🧩 应用情境
固定间隔测量并结合临床事件解释趋势。
## ⚠️ 易错点
每次分数波动都代表真实恶化或改善。
---PAGE---
# 【被动数字数据】
## 🧠 考试定义
由手机、可穿戴设备或平台行为自动产生的活动、睡眠、生理或使用模式数据。
## 💬 如何向来访者解释
这些数据可能提供生活趋势，但不会单独决定你的心理状态。
## 🧩 应用情境
在明确同意下用于补充情绪和功能趋势。
## ⚠️ 易错点
数据自动产生就无需同意，且能直接读出心理状态。
---PAGE---
# 【多模态评估】
## 🧠 考试定义
整合文本、语音、表情、生理和行为等多种数据来源形成评估信息。
## 💬 如何向来访者解释
多种数据可以互相补充，但每种都有误差和偏差。
## 🧩 应用情境
同时分析访谈语言和生理变化，但检查各来源一致性。
## ⚠️ 易错点
数据来源越多，结论就自动越准确。
---PAGE---
# 【算法偏差】
## 🧠 考试定义
模型因训练样本、标签、特征和部署情境不公平而对不同群体产生系统误差。
## 💬 如何向来访者解释
算法会继承数据中的偏差，需要针对不同群体持续检查。
## 🧩 应用情境
上线前检查不同性别、年龄和文化群体表现。
## ⚠️ 易错点
算法是客观数学，因此不会有文化或社会偏差。
---PAGE---
# 【数字隐私】
## 🧠 考试定义
对敏感心理、行为和生理数据进行最小化收集、明确授权、安全保存和用途限制。
## 💬 如何向来访者解释
我们只收集必要数据，并清楚说明用途、访问者和退出方式。
## 🧩 应用情境
说明采集哪些数据、谁访问、保存多久和如何退出。
## ⚠️ 易错点
去掉姓名就完全没有重识别风险。
---PAGE---
# 【专业责任】
## 🧠 考试定义
AI和数字工具提供辅助信息，最终选择、解释、风险处置和沟通责任仍由胜任的专业人员承担。
## 💬 如何向来访者解释
技术可以辅助判断，但专业人员仍要核查、解释并对处置负责。
## 🧩 应用情境
算法提示高风险时由专业人员及时复核并启动流程。
## ⚠️ 易错点
系统自动给出结果后咨询师无需检查或负责。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
机构计划用手机数据和AI语音分析自动筛查抑郁与自杀风险，并把高风险名单直接发给管理者。请评估该方案。
## 📌 参考思路
参考要点：明确评估目的和模型效度；取得具体知情同意并实施数据最小化；检查算法偏差、误报漏报和群体适用性；高风险必须由专业人员及时复核，不能由算法直接诊断；限定管理者访问和用途；建立紧急处置、退出、申诉、数据保存与安全机制；持续监测效果。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid;
